<?php
/** TEMP PS S1620 run e2d — D: dev-pastas v1.0 → v1.1 (md5 sargas, kopija, token_get_all, ping-atkūrimas) · Q: versija + Pragma eilutės 57–100 / 200–260 / 288–331 (tik skaitymas). */
add_action('init', function(){
  if (!isset($_GET['ps_e2d'])) return;
  $f=strtoupper(sanitize_key($_GET['ps_e2d'])); $o=array('v'=>'S1620 e2d','f'=>$f); global $wpdb; $p=$wpdb->prefix; set_time_limit(200);
  $o['temp_istrinta']=(int)$wpdb->query("DELETE FROM {$p}snippets WHERE name LIKE 'TEMP%' AND active=0");
  $J=function($o){ header('Content-Type: application/json'); echo json_encode($o,JSON_UNESCAPED_UNICODE|JSON_PARTIAL_OUTPUT_ON_ERROR); exit; };
  $ping=function(){ $r=wp_remote_get(admin_url('admin-ajax.php?action=heartbeat'),array('timeout'=>90,'sslverify'=>false)); $b=(string)wp_remote_retrieve_body($r); return array('code'=>wp_remote_retrieve_response_code($r),'fatal'=>(int)(stripos($b,'Fatal error')!==false||stripos($b,'Parse error')!==false)); };
  $fp=WPMU_PLUGIN_DIR.'/petshop-dev-pastas.php'; $up=wp_upload_dir(); $bk=$up['basedir'].'/ps-backups/petshop-dev-pastas-v10-BACKUP-2026-09-06.php';
  try{
  if($f==='D'){
    $live=(string)file_get_contents($fp); $o['md5_pries']=md5($live); if(md5($live)!=='744c69c92bb8f362ca7e3ccc1b80ddc5'){ $o['STOP']='gyvo md5 nesutampa'; $J($o); }
    $n=base64_decode('',true); if($n===false||md5($n)!=='ed7e80a87be1994244a565385fe46af0'){ $o['STOP']='b64/md5 naujo'; $J($o); }
    try{ token_get_all($n,TOKEN_PARSE); }catch(Throwable $e){ $o['STOP']='token: '.$e->getMessage(); $J($o); }
    if(!is_dir(dirname($bk))) wp_mkdir_p(dirname($bk)); $o['kopija']=(int)file_put_contents($bk,$live);
    $o['irasyta']=(int)file_put_contents($fp,$n); if(function_exists('opcache_invalidate')) opcache_invalidate($fp,true);
    $o['ping']=$ping(); if($o['ping']['fatal']||$o['ping']['code']>=500){ file_put_contents($fp,$live); $o['ATKURTA']=md5_file($fp); }
    $o['md5_po']=md5_file($fp); $J($o);
  }
  if($f==='Q'){
    $o['versija']=class_exists('Petshop_Dev_Pastas')?Petshop_Dev_Pastas::VERSIJA:'NĖRA'; $o['md5']=md5_file($fp); $o['kopija_yra']=file_exists($bk)?md5_file($bk):0; $o['ping']=$ping();
    $L=explode("\n",(string)file_get_contents(WP_PLUGIN_DIR.'/petshop-pragma/petshop-pragma.php')); $o['pragma']=array();
    foreach(array(array(57,100),array(200,260),array(288,331)) as $rg){ foreach(array_slice($L,$rg[0]-1,$rg[1]-$rg[0]+1) as $k=>$l){ $t=trim($l); if($t!==''&&!preg_match('#^(//|\*|/\*)#',$t)) $o['pragma'][]=($rg[0]+$k).': '.mb_substr($t,0,170); } }
    $o['pragma_log']=array_map(function($e){return ($e['time']??'').' '.mb_substr($e['message']??'',0,110);},array_slice((array)get_option('petshop_pragma_log',array()),-6));
    $o['prod_mode']=get_option('petshop_pragma_production_mode',false); $o['next']=($n=wp_next_scheduled('petshop_pragma_monthly_export'))?date('Y-m-d H:i',$n):null;
    $o['temp_liko']=(int)$wpdb->get_var("SELECT COUNT(*) FROM {$p}snippets WHERE name LIKE 'TEMP%'"); $J($o);
  }
  }catch(Throwable $e){ $o['FATAL']=$e->getMessage().' @'.basename($e->getFile()).':'.$e->getLine(); }
  $J($o);
},99);
